import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Script Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/script-conventions.md","filePath":"reference/script-conventions.md"}'),r={name:"reference/script-conventions.md"};function n(d,e,o,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="script-conventions" tabindex="-1">Script Conventions <a class="header-anchor" href="#script-conventions" aria-label="Permalink to &quot;Script Conventions&quot;">​</a></h1><p>dbsh uses Flyway-style naming for migration scripts.</p><h2 id="file-patterns" tabindex="-1">File patterns <a class="header-anchor" href="#file-patterns" aria-label="Permalink to &quot;File patterns&quot;">​</a></h2><h3 id="versioned-migrations-v-prefix" tabindex="-1">Versioned migrations (<code>V</code> prefix) <a class="header-anchor" href="#versioned-migrations-v-prefix" aria-label="Permalink to &quot;Versioned migrations (\`V\` prefix)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Database/Migrations/Schema/V001__CreateUsersTable.sql</span></span>
<span class="line"><span>Database/Migrations/Schema/V002__AddEmailColumn.sql</span></span>
<span class="line"><span>Database/Migrations/Schema/V20260617120000__CreateOrders.sql</span></span></code></pre></div><ul><li><code>V</code> = versioned (applied once)</li><li>Version is a globally-unique, auto-incrementing integer rendered zero-padded (<code>001</code>, <code>002</code>, ...). <code>dbsh create</code> picks the next free number across all type folders.</li><li>A UTC timestamp (<code>20260617120000</code>) is available via <code>dbsh create --timestamp</code> for teams that prefer date-ordered versions</li><li><code>__</code> (double underscore) separates the version from the name</li><li>The name should be PascalCase, underscores allowed</li></ul><h3 id="repeatable-migrations-r-prefix" tabindex="-1">Repeatable migrations (<code>R</code> prefix) <a class="header-anchor" href="#repeatable-migrations-r-prefix" aria-label="Permalink to &quot;Repeatable migrations (\`R\` prefix)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Database/Migrations/Schema/R__RefreshUserView.sql</span></span></code></pre></div><ul><li><code>R</code> = repeatable (re-applied every time the checksum changes)</li><li>No version number</li></ul><h3 id="rollback-scripts-u-prefix" tabindex="-1">Rollback scripts (<code>U</code> prefix) <a class="header-anchor" href="#rollback-scripts-u-prefix" aria-label="Permalink to &quot;Rollback scripts (\`U\` prefix)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Database/Migrations/Rollback/U001__Rollback_CreateUsersTable.sql</span></span></code></pre></div><ul><li><code>U</code> = undo</li><li>The version must match the forward migration&#39;s version (without the <code>V</code> prefix)</li><li>Paired with their forward counterparts</li></ul><h2 id="directory-structure" tabindex="-1">Directory structure <a class="header-anchor" href="#directory-structure" aria-label="Permalink to &quot;Directory structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Database/Migrations/</span></span>
<span class="line"><span>  Schema/          versioned DDL (V prefix)</span></span>
<span class="line"><span>  Data/            seed/migration data (V prefix)</span></span>
<span class="line"><span>  Patch/           hotfix DDL/DML (V prefix)</span></span>
<span class="line"><span>  Rollback/        undo scripts (U prefix)</span></span></code></pre></div><h2 id="metadata-headers" tabindex="-1">Metadata headers <a class="header-anchor" href="#metadata-headers" aria-label="Permalink to &quot;Metadata headers&quot;">​</a></h2><p>Optional metadata in the SQL file:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Migration: CreateUsersTable</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Author: jane.doe</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Created: 2025-01-15</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Description: Creates the users table</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Depends: V000__InitialSetup.sql</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>-- Migration:</code></td><td>No</td><td>Migration name</td></tr><tr><td><code>-- Author:</code></td><td>No</td><td>Who wrote this migration</td></tr><tr><td><code>-- Created:</code></td><td>No</td><td>Creation date</td></tr><tr><td><code>-- Description:</code></td><td>No</td><td>What this migration does</td></tr><tr><td><code>-- Depends:</code></td><td>No</td><td>Comma-separated list of prerequisite scripts</td></tr></tbody></table><h2 id="checksums" tabindex="-1">Checksums <a class="header-anchor" href="#checksums" aria-label="Permalink to &quot;Checksums&quot;">​</a></h2><p>dbsh computes a SHA-256 checksum for each script. The checksum is computed after normalizing line endings to LF. This ensures cross-platform consistency.</p><p>If a previously-applied script is edited in place, the checksum changes, and <code>dbsh migrate</code> will refuse to deploy (checksum drift detection). You must either:</p><ol><li>Create a new migration instead of editing existing ones, or</li><li>Use <code>dbsh repair</code> to clear the history, then re-apply</li></ol><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><p><code>dbsh status</code> reports one state per migration:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Pending</code></td><td>Script on disk, not yet applied</td></tr><tr><td><code>Applied</code></td><td>Applied successfully</td></tr><tr><td><code>Failed</code></td><td>Applied with errors (re-queue with <code>dbsh repair</code>)</td></tr><tr><td><code>RolledBack</code></td><td>Undo script ran against it</td></tr><tr><td><code>Drifted</code></td><td>Applied, but the file was edited afterwards</td></tr><tr><td><code>Missing</code></td><td>Recorded in history, but the script file no longer exists on disk</td></tr></tbody></table>`,25)])])}const b=t(r,[["render",n]]);export{u as __pageData,b as default};
